/** A source label is an identity, never an integer obtained by truncating it. */
export interface SourceVersePoint {
  number: number;
  part?: string;
}
export interface SourceVerseSegment {
  start: SourceVersePoint;
  end: SourceVersePoint;
}
export interface ParsedSourceVerseLabel {
  label: string;
  segments: SourceVerseSegment[];
}

const point = (value: string): SourceVersePoint | undefined => {
  const match = value.match(/^(\d+)([a-z])?$/i);
  if (!match || !Number.isSafeInteger(Number(match[1]))) {
    return undefined;
  }
  return { number: Number(match[1]), ...(match[2] ? { part: match[2].toLowerCase() } : {}) };
};
const bound = (value: SourceVersePoint, end: boolean): [number, number] => [
  value.number,
  value.part ? value.part.charCodeAt(0) - 96 : end ? 27 : 0,
];
const compare = (a: [number, number], b: [number, number]) => a[0] - b[0] || a[1] - b[1];

export function parseSourceVerseLabel(value: unknown): ParsedSourceVerseLabel | undefined {
  if (typeof value !== 'string' && typeof value !== 'number') {
    return undefined;
  }
  const label = String(value).trim();
  if (!label) {
    return undefined;
  }
  // The original spelling remains in label. Separators only affect interpretation.
  const input = label.startsWith('[') && label.endsWith(']') ? label.slice(1, -1) : label;
  const segments: SourceVerseSegment[] = [];
  for (const segment of input.split(/[,;]/)) {
    const range = segment.trim().split(/\s*[-–—]\s*/);
    if (range.length > 2) {
      return undefined;
    }
    const start = point(range[0]);
    const end = point(range[1] ?? range[0]);
    if (!start || !end || compare(bound(start, false), bound(end, true)) > 0) {
      return undefined;
    }
    segments.push({ start, end });
  }
  return { label, segments };
}

/** Selection membership only: this does NOT establish a KJV content correspondence. */
export function sourceVerseLabelsOverlap(source: unknown, requested: unknown): boolean {
  const a = parseSourceVerseLabel(source),
    b = parseSourceVerseLabel(requested);
  return (
    !!a &&
    !!b &&
    a.segments.some((left) =>
      b.segments.some(
        (right) =>
          compare(bound(left.start, false), bound(right.end, true)) <= 0 &&
          compare(bound(right.start, false), bound(left.end, true)) <= 0,
      ),
    )
  );
}

/** Retain legacy numeric values where lossless; keep every nonnumeric source label. */
export function sourceVerseLabelValue(value: unknown): string | number {
  const parsed = parseSourceVerseLabel(value);
  if (!parsed) {
    throw new Error('Unrecognized source verse label.');
  }
  const number = Number(parsed.label);
  return Number.isSafeInteger(number) && String(number) === parsed.label ? number : parsed.label;
}

/** Stable ordering for raw verse files; chapter-array source order remains authoritative. */
export function compareSourceVerseLabels(a: unknown, b: unknown): number {
  const left = parseSourceVerseLabel(a),
    right = parseSourceVerseLabel(b);
  if (!left || !right) {
    throw new Error('Unrecognized source verse label.');
  }
  return compare(bound(left.segments[0].start, false), bound(right.segments[0].start, false));
}
