import { bibleChapterUrls } from '../data/bibleEditions';
import { parseSourceVerseLabel } from '../utils/sourceVerseLabels';

export interface BibleVerse {
  id: string | number;
  book: string;
  chapter: string | number;
  verse: string | number;
  text: string;
}

let jsDelivrUnavailable = false;

/** A 50 MB package rejection applies to the repository, so subsequent reads use GitHub directly. */
export async function loadBibleChapter(
  translation: string,
  book: string,
  chapter: number,
  signal?: AbortSignal,
): Promise<BibleVerse[]> {
  const urls = bibleChapterUrls(translation, book, chapter);
  for (const url of jsDelivrUnavailable
    ? urls.filter((candidate) => !candidate.includes('cdn.jsdelivr.net'))
    : urls) {
    if (signal?.aborted) {
      throw new DOMException('Cancelled', 'AbortError');
    }
    const controller = new AbortController();
    const abort = () => controller.abort();
    signal?.addEventListener('abort', abort, { once: true });
    const timeout = setTimeout(abort, 8000);
    try {
      const response = await fetch(url, { signal: controller.signal });
      if (response.status === 403 && url.includes('cdn.jsdelivr.net')) {
        const reason = await response.text();
        if (/Package size exceeded the configured limit/i.test(reason)) {
          jsDelivrUnavailable = true;
        }
      }
      if (!response.ok) {
        continue;
      }
      const rows: unknown = await response.json();
      if (
        !Array.isArray(rows) ||
        rows.length === 0 ||
        !rows.every(
          (row) =>
            row &&
            typeof row.book === 'string' &&
            row.book.trim().toLowerCase() === book.trim().toLowerCase() &&
            Number(row.chapter) === chapter &&
            // Preserve stored references, including Ezra 9:0's existing WordPress identity.
            parseSourceVerseLabel(row.verse) !== undefined &&
            typeof row.text === 'string' &&
            (typeof row.id === 'string' || typeof row.id === 'number'),
        ) ||
        !rows.some((row) => row.text.trim())
      ) {
        continue;
      }
      const labels = rows.map((row) => String(row.verse).trim());
      if (new Set(labels).size !== labels.length) {
        continue;
      }
      if (signal?.aborted) {
        throw new DOMException('Cancelled', 'AbortError');
      }
      return rows;
    } catch (error) {
      if (signal?.aborted) {
        throw error;
      }
    } finally {
      clearTimeout(timeout);
      signal?.removeEventListener('abort', abort);
    }
  }
  throw new Error('Unable to load this Bible passage. Please try again.');
}
