import { BIBLE_EDITIONS, AvailableLocale } from '../data/bibleEditions';

export type WordleLocale = AvailableLocale;
export const WORDLE_LOCALES = [...new Set(BIBLE_EDITIONS.map((edition) => edition.locale))];
export const isWordleLocale = (value: unknown): value is WordleLocale =>
  WORDLE_LOCALES.includes(value as WordleLocale);
export const normalizeWordle = (value: string): string =>
  value.normalize('NFC').replace(/ß/g, 'ẞ').toUpperCase();
export const wordleLetters = (word: string): string[] => Array.from(normalizeWordle(word));
export const wordleDraft = (value: string): string =>
  wordleLetters(value)
    .filter((letter) => /^\p{L}$/u.test(letter))
    .slice(0, 5)
    .join('');
export const wordlePuzzle = (locale: WordleLocale = 'en') => `${locale}-v1`;
export const wordleStorageKey = (owner: string | null, day: string, locale: WordleLocale = 'en') =>
  locale === 'en'
    ? `revelationary.wordle.v1.${owner || 'guest'}.${day}`
    : `revelationary.wordle.v2.${locale}.${owner || 'guest'}.${day}`;
export type LetterResult = 'correct' | 'present' | 'absent';
export interface WordleState {
  version: 1;
  locale?: WordleLocale;
  puzzle?: string;
  day: string;
  guesses: string[];
  startedAt?: number;
  finishedAt?: number;
  draft?: string;
}
export const utcDay = (date = new Date()): string => date.toISOString().slice(0, 10);
export const nextWordleDay = (day: string): string =>
  new Date(Date.parse(`${day}T00:00:00Z`) + 86400000).toISOString();
export function dailyWord(day: string, words: string[]): string {
  const ordinal = Math.floor(Date.parse(`${day}T00:00:00Z`) / 86400000);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || !Number.isFinite(ordinal) || !words.length) {
    throw new Error('Invalid daily puzzle');
  }
  return words[(((ordinal * 7919 + 31) % words.length) + words.length) % words.length];
}
export function scoreWordleGuess(answer: string, guess: string): LetterResult[] {
  const answerLetters = wordleLetters(answer);
  const guessLetters = wordleLetters(guess);
  const result: LetterResult[] = Array(5).fill('absent');
  const remaining = new Map<string, number>();
  for (let i = 0; i < 5; i++) {
    if (guessLetters[i] === answerLetters[i]) {
      result[i] = 'correct';
    } else {
      remaining.set(answerLetters[i], (remaining.get(answerLetters[i]) || 0) + 1);
    }
  }
  for (let i = 0; i < 5; i++) {
    if (result[i] !== 'correct' && (remaining.get(guessLetters[i]) || 0) > 0) {
      result[i] = 'present';
      remaining.set(guessLetters[i], (remaining.get(guessLetters[i]) || 0) - 1);
    }
  }
  return result;
}
export function wordleOutcome(state: WordleState, words: string[]): 'playing' | 'won' | 'lost' {
  return state.guesses.includes(dailyWord(state.day, words))
    ? 'won'
    : state.guesses.length >= 6
      ? 'lost'
      : 'playing';
}
export function validGuesses(
  guesses: unknown,
  day: string,
  words: string[],
  allowed = words,
): guesses is string[] {
  if (
    !Array.isArray(guesses) ||
    guesses.length > 6 ||
    !guesses.every((guess) => typeof guess === 'string' && allowed.includes(guess))
  ) {
    return false;
  }
  const win = guesses.indexOf(dailyWord(day, words));
  return win === -1 || win === guesses.length - 1;
}
export function restoreWordle(
  raw: string | null,
  day: string,
  words: string[],
  allowed = words,
  locale: WordleLocale = 'en',
): WordleState {
  const identity = locale === 'en' ? {} : { locale, puzzle: wordlePuzzle(locale) };
  try {
    const saved = raw && raw.length < 1000 ? JSON.parse(raw) : null;
    if (
      saved?.version === 1 &&
      (saved.locale || 'en') === locale &&
      (saved.puzzle || 'en-v1') === wordlePuzzle(locale) &&
      saved.day === day &&
      validGuesses(saved.guesses, day, words, allowed)
    ) {
      const state: WordleState = { version: 1, ...identity, day, guesses: saved.guesses };
      if (
        typeof saved.draft === 'string' &&
        wordleDraft(saved.draft) === saved.draft &&
        wordleOutcome(state, words) === 'playing'
      ) {
        state.draft = saved.draft;
      }
      const start = saved.startedAt,
        finish = saved.finishedAt;
      const midnight = Date.parse(`${day}T00:00:00Z`);
      if (Number.isSafeInteger(start) && start >= midnight && start < midnight + 86400000) {
        if (wordleOutcome(state, words) === 'playing' && finish === undefined) {
          state.startedAt = start;
        } else if (
          Number.isSafeInteger(finish) &&
          finish >= start &&
          finish < midnight + 86400000
        ) {
          state.startedAt = start;
          state.finishedAt = finish;
        }
      }
      return state;
    }
  } catch {
    // A malformed/old browser snapshot cannot grant another account attempt.
  }
  return { version: 1, ...identity, day, guesses: [] };
}
/** Old progress without a start time remains untimed; never invent a faster time. */
export function startWordle(state: WordleState, now = Date.now()): WordleState {
  return state.startedAt === undefined &&
    state.guesses.length === 0 &&
    utcDay(new Date(now)) === state.day
    ? { ...state, startedAt: now }
    : state;
}
export function addWordleGuess(
  state: WordleState,
  guess: string,
  words: WordList,
  now = Date.now(),
): WordleState {
  if (wordleOutcome(state, words.words) !== 'playing' || !words.allowedGuesses.includes(guess)) {
    return state;
  }
  const next = { ...state, guesses: [...state.guesses, guess] };
  return wordleOutcome(next, words.words) !== 'playing' && state.startedAt !== undefined
    ? { ...next, finishedAt: now }
    : next;
}
export const validElapsedSeconds = (value: unknown): value is number | null =>
  value === null ||
  (typeof value === 'number' && Number.isInteger(value) && value >= 0 && value <= 86400);
export function elapsedWordleSeconds(state: WordleState, now = Date.now()): number | null {
  if (state.startedAt === undefined) {
    return null;
  }
  const seconds = Math.floor(((state.finishedAt ?? now) - state.startedAt) / 1000);
  return validElapsedSeconds(seconds) ? seconds : null;
}
export function formatWordleTime(seconds: number | null | undefined): string {
  return seconds === null || seconds === undefined
    ? '—'
    : `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}
export interface DailyResult {
  day: string;
  outcome: 'won' | 'lost';
  attempts: number;
  elapsedSeconds?: number | null;
}
export interface AccountWordle {
  version: 1;
  locale?: WordleLocale;
  puzzle?: string;
  owner: number;
  day: string;
  today: (DailyResult & { revision: number; listed: boolean; publicName: string }) | null;
  history: DailyResult[];
  currentStreak: number;
  longestStreak: number;
  trophies: string[];
}
export interface WordList {
  version: 1 | 2;
  locale?: WordleLocale;
  puzzle?: string;
  words: string[];
  allowedGuesses: string[];
  input?: { aliases: Record<string, string>; pinyin: Record<string, string> };
}
export const normalizeWordleGuess = (value: string, words: WordList): string => {
  const normalized = normalizeWordle(value);
  if (words.allowedGuesses.includes(normalized)) {
    return normalized;
  }
  if (words.input?.aliases[normalized]) {
    return words.input.aliases[normalized];
  }
  // A reader can mix simplified and traditional characters in the same valid phrase.
  // Resolve only an unambiguous, already-verified dictionary entry.
  const letters = wordleLetters(normalized);
  const matches = new Set<string>();
  for (const [alias, canonical] of Object.entries(words.input?.aliases || {})) {
    const simplified = wordleLetters(alias),
      original = wordleLetters(canonical);
    if (
      letters.length === 5 &&
      letters.every((letter, i) => letter === simplified[i] || letter === original[i])
    ) {
      matches.add(canonical);
    }
  }
  return matches.size === 1 ? [...matches][0] : normalized;
};
export function parseWordList(data: unknown, locale: WordleLocale = 'en'): WordList {
  const d = data as WordList;
  if (
    !d ||
    (locale === 'en'
      ? d.version !== 1
      : d.version !== 2 || d.locale !== locale || d.puzzle !== wordlePuzzle(locale)) ||
    !Array.isArray(d.words) ||
    (locale === 'en' ? d.words.length !== 150 : d.words.length < 30) ||
    !Array.isArray(d.allowedGuesses) ||
    ![...d.words, ...d.allowedGuesses].every(
      (w) => typeof w === 'string' && /^\p{L}{5}$/u.test(w) && normalizeWordle(w) === w,
    ) ||
    new Set(d.words).size !== d.words.length ||
    new Set(d.allowedGuesses).size !== d.allowedGuesses.length ||
    !d.words.every((w) => d.allowedGuesses.includes(w))
  ) {
    throw new Error('Invalid word list');
  }
  if (
    locale === 'zh-hans' &&
    (!d.input ||
      !d.input.aliases ||
      !d.input.pinyin ||
      !Object.entries(d.input.aliases).every(
        ([alias, word]) => /^\p{L}{5}$/u.test(alias) && d.allowedGuesses.includes(word),
      ) ||
      !Object.entries(d.input.pinyin).every(
        ([letter, syllable]) =>
          /^\p{L}$/u.test(letter) && typeof syllable === 'string' && /^[a-z]+$/.test(syllable),
      ))
  ) {
    throw new Error('Invalid Chinese input dictionary');
  }
  return d;
}
const validDay = (day: unknown): day is string =>
  typeof day === 'string' &&
  /^\d{4}-\d{2}-\d{2}$/.test(day) &&
  Number.isFinite(Date.parse(`${day}T00:00:00Z`)) &&
  new Date(`${day}T00:00:00Z`).toISOString().slice(0, 10) === day;
const validResult = (r: DailyResult) =>
  r &&
  validDay(r.day) &&
  ['won', 'lost'].includes(r.outcome) &&
  Number.isInteger(r.attempts) &&
  r.attempts >= 1 &&
  r.attempts <= 6 &&
  (r.outcome !== 'lost' || r.attempts === 6) &&
  validElapsedSeconds(r.elapsedSeconds ?? null);
export function parseAccountWordle(data: unknown, locale: WordleLocale = 'en'): AccountWordle {
  const d = data as AccountWordle;
  if (
    !d ||
    d.version !== 1 ||
    (d.locale || 'en') !== locale ||
    (d.puzzle || 'en-v1') !== wordlePuzzle(locale) ||
    !Number.isInteger(d.owner) ||
    d.owner < 1 ||
    !validDay(d.day) ||
    !Array.isArray(d.history) ||
    !d.history.every(validResult) ||
    new Set(d.history.map((r) => r.day)).size !== d.history.length ||
    !Number.isInteger(d.currentStreak) ||
    d.currentStreak < 0 ||
    !Number.isInteger(d.longestStreak) ||
    d.longestStreak < d.currentStreak ||
    !Array.isArray(d.trophies) ||
    !d.trophies.every((t) => ['firstWin', 'threeStreak', 'sevenStreak'].includes(t)) ||
    (d.today !== null &&
      (!validResult(d.today) ||
        d.today.day !== d.day ||
        !Number.isInteger(d.today.revision) ||
        d.today.revision < 1 ||
        typeof d.today.listed !== 'boolean' ||
        typeof d.today.publicName !== 'string' ||
        d.today.publicName.length > 48))
  ) {
    throw new Error('Invalid account game response');
  }
  return d;
}
