/**
 * Translate a Bible book name using i18n
 * This function should be called from within a component that has access to useTranslation
 */
export const translateBookName = (
  book: string,
  t: (key: string, options?: any) => string | object,
): string => {
  if (!book) {
    return '';
  }

  const translationKey = normalizeBookName(book);
  if (translationKey) {
    const translated = t(translationKey);
    return String(translated);
  }

  // Fallback: return capitalized book name if translation not found
  return book.charAt(0).toUpperCase() + book.slice(1).toLowerCase();
};

