import { normalizeBookName } from './bookTranslations';
import { hasBibleSourceReference } from '../data/bibleSourceReferences';

export type HighlightVerse = {
  book: string;
  chapter: string | number;
  verse: string | number;
  id?: string | number;
  translation?: string;
};
export type HighlightDocument = {
  revision: number;
  entries: Record<string, string>;
  palette: Record<string, string>;
  preferred: string;
};
export type HighlightChange =
  | { kind: 'verse'; key: string; color: string | null }
  | { kind: 'palette'; color: string; label: string }
  | {
      kind: 'palette-edit';
      palette: Record<string, string>;
      preferred: string;
      verse?: { key: string; color: string | null };
    };
export const DEFAULT_HIGHLIGHTS: HighlightDocument = {
  revision: 0,
  entries: {},
  palette: { '#ffff00': '', '#f44336': '', '#2196f3': '', '#4caf50': '', '#9c27b0': '' },
  preferred: '#ffff00',
};
export const normalizeHighlightColor = (color: string): string | null =>
  /^#[0-9a-f]{6}$/i.test(color) ? color.toLowerCase() : null;
// Read compatibility for identities accepted by the previous client/server.
// This is not used to create new references that do not exist in a source Bible.
const legacyHighlightKey = (
  verse: HighlightVerse,
  translation = verse.translation || 'kjv',
): string => {
  const book = normalizeBookName(verse.book)
    .replace(/^books\./, '')
    .toLowerCase();
  const chapter = Number(verse.chapter),
    number = Number(verse.verse);
  if (
    !book ||
    !/^[a-z0-9-]{1,24}$/.test(translation) ||
    !Number.isInteger(chapter) ||
    chapter < 1 ||
    chapter > 150 ||
    !Number.isInteger(number) ||
    number < 1 ||
    number > 200
  ) {
    return '';
  }
  return `${translation}:${book}:${chapter}:${number}`;
};
export const highlightKey = (
  verse: HighlightVerse,
  translation = verse.translation || 'kjv',
): string => {
  const edition = verse.translation || translation;
  const book = normalizeBookName(verse.book)
    .replace(/^books\./, '')
    .toLowerCase();
  const chapter = Number(verse.chapter);
  const label = String(verse.verse).trim();
  if (!Number.isSafeInteger(chapter) || !hasBibleSourceReference(edition, book, chapter, label)) {
    return '';
  }
  return `${edition}:${book}:${chapter}:${label}`;
};
export const highlightTextColor = (color: string): '#000000' | '#ffffff' => {
  if (!normalizeHighlightColor(color)) {
    return '#000000';
  }
  const rgb = [1, 3, 5]
    .map((i) => parseInt(color.slice(i, i + 2), 16) / 255)
    .map((c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  const luminance = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
  return (luminance + 0.05) / 0.05 >= 1.05 / (luminance + 0.05) ? '#000000' : '#ffffff';
};
const record = (value: unknown): value is Record<string, unknown> =>
  !!value && typeof value === 'object' && !Array.isArray(value);
export function parseHighlightDocument(value: unknown): HighlightDocument {
  if (
    !record(value) ||
    !Number.isSafeInteger(value.revision) ||
    Number(value.revision) < 0 ||
    !record(value.entries) ||
    !record(value.palette) ||
    typeof value.preferred !== 'string' ||
    !normalizeHighlightColor(value.preferred)
  ) {
    throw new Error('Invalid highlights response. Your saved highlights have not been replaced.');
  }
  if (Object.keys(value.entries).length > 70000 || Object.keys(value.palette).length > 64) {
    throw new Error('Invalid highlights response.');
  }
  for (const [key, color] of Object.entries(value.entries)) {
    const parts = key.split(':');
    if (
      parts.length !== 4 ||
      (highlightKey({ book: parts[1], chapter: parts[2], verse: parts[3] }, parts[0]) !== key &&
        legacyHighlightKey({ book: parts[1], chapter: parts[2], verse: parts[3] }, parts[0]) !==
          key) ||
      typeof color !== 'string' ||
      normalizeHighlightColor(color) !== color
    ) {
      throw new Error('Invalid saved verse colour.');
    }
  }
  for (const [color, label] of Object.entries(value.palette)) {
    if (
      normalizeHighlightColor(color) !== color ||
      typeof label !== 'string' ||
      [...label].length > 48
    ) {
      throw new Error('Invalid saved colour label.');
    }
  }
  return {
    revision: Number(value.revision),
    entries: value.entries as Record<string, string>,
    palette: value.palette as Record<string, string>,
    preferred: value.preferred,
  };
}

export type PaletteRow = { id: string; original: string | null; color: string; label: string };
/** Merge only edited rows onto the newest snapshot, preserving unrelated device edits. */
export function mergePaletteDraft(
  original: HighlightDocument,
  latest: HighlightDocument,
  rows: PaletteRow[],
): Record<string, string> {
  const colors = rows.map((row) => normalizeHighlightColor(row.color));
  if (colors.some((color) => !color) || new Set(colors).size !== colors.length) {
    throw new Error('Choose a different colour for each row.');
  }
  const changed = rows.filter(
    (row) =>
      !row.original ||
      row.color !== row.original ||
      row.label.trim() !== (original.palette[row.original] || ''),
  );
  const palette = { ...latest.palette };
  changed.forEach((row) => {
    if (row.original) {
      delete palette[row.original];
    }
  });
  for (const row of changed) {
    if (Object.prototype.hasOwnProperty.call(palette, row.color)) {
      // A lost save response followed by refresh may already contain this rename.
      if (
        row.original &&
        !Object.prototype.hasOwnProperty.call(latest.palette, row.original) &&
        palette[row.color] === row.label.trim()
      ) {
        continue;
      }
      throw new Error('That colour was added elsewhere. Choose another.');
    }
    palette[row.color] = row.label.trim();
  }
  if (Object.keys(palette).length > 64) {
    throw new Error('Your palette can contain up to 64 colours.');
  }
  const ordered: Record<string, string> = {};
  for (const color of Object.keys(latest.palette)) {
    const next = changed.find((row) => row.original === color)?.color || color;
    if (Object.prototype.hasOwnProperty.call(palette, next)) {
      ordered[next] = palette[next];
    }
  }
  return { ...ordered, ...palette };
}
