import sv from './locales/sv.json';
import id from './locales/id.json';
import nl from './locales/nl.json';
import vi from './locales/vi.json';
import en from './locales/en.json';
import es from './locales/es.json';
import de from './locales/de.json';
import zh from './locales/zh-hans.json';
import it from './locales/it.json';
import cs from './locales/cs.json';

// Pending languages are stored on disk and become importable after their Bible passes validation.
export const readerCatalogs = { en, es, de, 'zh-hans': zh, it, cs, sv, id, nl, vi };
export type ReaderLocale = keyof typeof readerCatalogs;
const learningCatalogs = { ...readerCatalogs, cs };
type LearningLocale = keyof typeof learningCatalogs;
const learningLocale = (language: string): LearningLocale => {
  const locale = language === 'zh' ? 'zh-hans' : language;
  return Object.prototype.hasOwnProperty.call(learningCatalogs, locale)
    ? (locale as LearningLocale)
    : 'en';
};
export function readerLocale(language: string): ReaderLocale | undefined {
  const locale = language === 'zh' ? 'zh-hans' : language;
  return Object.prototype.hasOwnProperty.call(readerCatalogs, locale)
    ? (locale as ReaderLocale)
    : undefined;
}
export function hebrewUnavailableMessage(language: string): string {
  const messages: Record<string, string> = {
    en: "This Hebrew learning tool isn't available in this translation.",
    es: 'Esta herramienta de aprendizaje de hebreo no está disponible en esta traducción.',
    de: 'Dieses Hebräisch-Lernwerkzeug ist in dieser Übersetzung nicht verfügbar.',
    zh: '此译本暂不提供希伯来语学习工具。',
    'zh-hans': '此译本暂不提供希伯来语学习工具。',
    it: 'Questo strumento per imparare l’ebraico non è disponibile in questa traduzione.',
  };
  return messages[language] || learningCatalogs[learningLocale(language)].hebrewExplorer.noData;
}

export function hebrewResourceMessage(
  language: string,
  kind: 'unavailable' | 'request-failed' | 'retry',
): string {
  const messages: Partial<Record<LearningLocale, Record<typeof kind, string>>> = {
    en: {
      unavailable: 'Hebrew learning content is unavailable for this passage.',
      'request-failed': 'Hebrew content could not be loaded. Please try again.',
      retry: 'Try again',
    },
    es: {
      unavailable: 'El contenido para aprender hebreo no está disponible para este pasaje.',
      'request-failed': 'No se pudo cargar el contenido hebreo. Inténtalo de nuevo.',
      retry: 'Reintentar',
    },
    de: {
      unavailable: 'Für diese Bibelstelle sind keine Hebräisch-Lerninhalte verfügbar.',
      'request-failed':
        'Die hebräischen Inhalte konnten nicht geladen werden. Bitte versuche es erneut.',
      retry: 'Erneut versuchen',
    },
    'zh-hans': {
      unavailable: '此段经文暂不提供希伯来语学习内容。',
      'request-failed': '未能加载希伯来语内容，请重试。',
      retry: '重试',
    },
    it: {
      unavailable: 'Il contenuto per imparare l’ebraico non è disponibile per questo passo.',
      'request-failed': 'Impossibile caricare il contenuto ebraico. Riprova.',
      retry: 'Riprova',
    },
  };
  const catalog = learningCatalogs[learningLocale(language)];
  return (
    messages[learningLocale(language)]?.[kind] ||
    (kind === 'retry'
      ? catalog.games.retry
      : kind === 'unavailable'
        ? catalog.hebrewExplorer.noData
        : catalog.games.unavailable)
  );
}

export function getHebrewLesson(language: string) {
  const locale = language === 'zh' ? 'zh-hans' : language;
  return Object.prototype.hasOwnProperty.call(learningCatalogs, locale)
    ? learningCatalogs[locale as LearningLocale].additional.hebrewLearning
    : undefined;
}

