export function hasHebrewLearning(language: string): boolean {
  const lesson = getHebrewLesson(language);
  const dictionaries = new Set([
    'en',
    'es',
    'de',
    'zh',
    'zh-hans',
    'it',
    'cs',
    'nl',
    'sv',
    'pl',
    'id',
    'uk',
    'et',
    'fi',
    'hu',
    'nb',
    'pt-br',
  ]);
  if (!lesson || !dictionaries.has(language)) {
    return false;
  }
  const english = en.additional.hebrewLearning;
  const complete = (source: Record<string, string>, target: Record<string, string>) =>
    Object.keys(source).every((key) => typeof target[key] === 'string' && target[key].trim());
  return (
    complete(english.letters, lesson.letters) &&
    complete(english.combinations, lesson.combinations) &&
    complete(english.genesis1_1.phrases, lesson.genesis1_1.phrases) &&
    !!lesson.genesis1_1.insight.trim()
  );
}

