import generated from './bibleSourceReferences.generated.json';

type ChapterReferences = { ranges: number[][]; labels: string[] };
export const bibleSourceReferences: Readonly<
  Record<string, Record<string, Record<string, ChapterReferences>>>
> = generated.editions;

/** Exact stored identities; a comment's shared KJV anchor never replaces these. */
export function hasBibleSourceReference(
  edition: string,
  book: string,
  chapter: number,
  label: string,
): boolean {
  const references = bibleSourceReferences[edition]?.[book]?.[String(chapter)];
  if (!references) {
    return false;
  }
  if (references.labels.includes(label)) {
    return true;
  }
  const number = Number(label);
  return (
    Number.isSafeInteger(number) &&
    String(number) === label &&
    references.ranges.some(([start, end]) => number >= start && number <= end)
  );
}
